<?php require __DIR__.'/../config.php'; admin_required();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT * FROM tickets WHERE id=?");$s->execute([$id]);$t=$s->fetch();if(!$t)exit('Ticket not found.');$saved=flash(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($t['ticket_no'])?> — SupportHub</title><link rel="stylesheet" href="../assets/style.css"></head><body class="dashboard"><nav><a class="brand" href="../index.php"><span class="logo">S</span> SupportHub</a><div class="navlinks"><a href="index.php">All requests</a><a href="logout.php">Sign out</a></div></nav><main class="detail"><a class="back" href="index.php">← Back to requests</a><?php if($saved):?><div class="successbar"><?=e($saved)?></div><?php endif;?><div class="detailgrid"><section class="panel"><div class="tickethead"><div><span class="eyebrow"><?=e($t['ticket_no'])?></span><h1><?=e($t['subject'])?></h1></div><span class="badge <?=$t['status']?>"><?=e(ucfirst($t['status']))?></span></div><div class="meta"><span><?=e($t['name'])?> · <?=e($t['email'])?></span><span><?=e($t['category'])?></span><span><?=e(date('M j, Y H:i',strtotime($t['created_at'])))?></span></div><div class="message"><?=nl2br(e($t['message']))?></div></section><aside class="panel"><h3>Update request</h3><form method="post" action="update.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$t['id']?>"><label>Status<select name="status"><?php foreach(['open','pending','resolved','closed'] as $x):?><option <?=$t['status']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></label><label>Priority<select name="priority"><?php foreach(['low','normal','high','urgent'] as $x):?><option <?=$t['priority']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></label><label>Internal/support note<textarea name="admin_note" rows="7" placeholder="Add an update the customer can see..."><?=e($t['admin_note']??'')?></textarea></label><button class="primary">Save changes</button></form></aside></div></main></body></html>